(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.01+sy*0.008+t*0.5)*8;
  const w2y = Math.cos(sy*0.012-sx*0.006-t*0.4)*8;
  const wx = sx+w2x, wy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*40,0.14,2.1,0.6],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*50,0.11,1.8,1.3]
  ];
  let aS=0,iS=0,iS2=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    iS2+=Math.sin(d*f*0.5-t*sp*0.4+3.0)*amp;
  }
  const n=8,act=aS/n,inh=iS/n,inh2=iS2/n;
  const bg=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1)+Math.sin(wx*0.06+wy*0.02-t*0.5))/3+Math.sin((wx+wy)*0.12+t*2.5)*0.15+Math.sin((wx-wy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.8)*0.5)*0.3;
  const cell=Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15)+Math.sin((wx+wy)*0.1+t)*0.5+Math.sin(wx*0.2-wy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const raw=act-inh*0.6-inh2*0.3+bg*0.25+spiral*0.4+cell*0.2;
  const reaction=Math.tanh(raw*2.0);
  const edge=1.0-Math.abs(reaction);
  const glow=Math.exp(-edge*5)*0.3*(0.8+Math.sin(t*2)*0.2);
  const blend=reaction*0.7+cell*0.2+glow*0.1,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,45,85],[15,95,110],[25,150,130],[120,190,100],[220,200,60],[230,140,50],[200,70,60],[140,35,75],[60,15,60],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edgeBoost=Math.abs(reaction)>0.65?1.2:1.0;
  const angShift=Math.sin(ang*2+t*0.3)*0.05;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+angShift*40)*lum*edgeBoost))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeBoost))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f-angShift*30)*lum*edgeBoost))|0
  ];
}
